import { initializeApp } from "https://www.gstatic.com/firebasejs/10.12.2/firebase-app.js";
import { getFirestore, collection, getDocs, doc, getDoc } from "https://www.gstatic.com/firebasejs/10.12.2/firebase-firestore.js";

const firebaseConfig = {
  projectId: "seagull-menu-db-35",
  appId: "1:17567596488:web:207ff2936bd00f4a198afd",
  storageBucket: "seagull-menu-db-35.firebasestorage.app",
  apiKey: "AIzaSyCZCHNVr-SlZrC9Hp4IQUDHRgChR8ITJ8Y",
  authDomain: "seagull-menu-db-35.firebaseapp.com",
  messagingSenderId: "17567596488"
};

const app = initializeApp(firebaseConfig);
const db = getFirestore(app);

export async function getMenuData() {
    try {
        const querySnapshot = await getDocs(collection(db, "menu"));
        let fetchedData = {};
        querySnapshot.forEach((doc) => {
            fetchedData[doc.id] = doc.data().categories;
        });
        
        if (Object.keys(fetchedData).length > 0) {
            return fetchedData;
        }
    } catch (e) {
        console.error("Error fetching from Firestore, falling back to default.", e);
    }
    return DEFAULT_MENU_DATA;
}

export async function getInstagramFeed() {
    try {
        const docSnap = await getDoc(doc(db, "public", "instagram_feed"));
        if (docSnap.exists()) {
            return docSnap.data().feed;
        }
    } catch (error) {
        console.error("Error fetching Instagram feed:", error);
    }
    return null;
}
